data.output:
	ServerInstance string
	Model          string
}

func routeSnapshotCandidateIndex(snapshot modelsnapshot.ModelSnapshot) map[routeSnapshotCandidateKey]modelsnapshot.KnownModel {
	if len(snapshot.Models) == 0 {
		return nil
	}
	out := make(map[routeSnapshotCandidateKey]modelsnapshot.KnownModel, len(snapshot.Models))
	for _, row := range snapshot.Models {
		key := routeSnapshotCandidateKey{
			Provider:       strings.TrimSpace(row.Provider),
			Endpoint:       strings.TrimSpace(row.EndpointName),
			ServerInstance: strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance)),
			Model:          strings.TrimSpace(row.ID),
		}
		if key.Provider == "" || key.Model == "" {
			continue
		}
		if _, exists := out[key]; exists {
			continue
		}
		out[key] = row
	}
	return out
}

func routeSnapshotEvidenceForCandidate(candidate RouteCandidate, snapshot modelsnapshot.ModelSnapshot) (modelsnapshot.KnownModel, bool) {
	index := routeSnapshotCandidateIndex(snapshot)
	if len(index) == 0 {
		return modelsnapshot.KnownModel{}, false
	}
	provider := strings.TrimSpace(candidate.Provider)
	endpoint := strings.TrimSpace(candidate.Endpoint)
	serverInstance := strings.TrimSpace(candidate.ServerInstance)
	model := strings.TrimSpace(candidate.Model)
	if base, ep, ok := splitEndpointProviderRef(provider); ok {
		provider = base
		if endpoint == "" {
			endpoint = ep
		}
	}
	keys := []routeSnapshotCandidateKey{{
		Provider:       provider,
		Endpoint:       endpoint,
		ServerInstance: serverInstance,
		Model:          model,
	}}
	if endpoint == "" {
		keys = append(keys, routeSnapshotCandidateKey{
			Provider:       provider,
			ServerInstance: serverInstance,
			Model:          model,
		})
	}
	if serverInstance == "" {
		keys = append(keys, routeSnapshotCandidateKey{
			Provider: provider,
			Endpoint: endpoint,
			Model:    model,
		})
		if endpoint == "" {
			keys = append(keys, routeSnapshotCandidateKey{
				Provider: provider,
				Model:    model,
			})
		}
	}
	for _, key := range keys {
		if row, ok := index[key]; ok {
			return row, true
		}
	}
	for _, row := range snapshot.Models {
		rowProvider := strings.TrimSpace(row.Provider)
		rowEndpoint := strings.TrimSpace(row.EndpointName)
		rowServerInstance := strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance))
		if rowProvider != provider || strings.TrimSpace(row.ID) != model {
			continue
		}
		if endpoint != "" && rowEndpoint != endpoint {
			continue
		}
		if serverInstance != "" && rowServerInstance != serverInstance {
			continue
		}
		return row, true
	}
	return modelsnapshot.KnownModel{}, false
}

func applyRouteSnapshotEvidence(candidate *RouteCandidate, row modelsnapshot.KnownModel) {
	if candidate == nil {
		return
	}
	if candidate.ServerInstance == "" {
		candidate.ServerInstance = strings.TrimSpace(serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance))
	}
	candidate.SourceStatus = string(row.Status)
	candidate.AutoRoutable = row.AutoRoutable
	candidate.ExactPinOnly = row.ExactPinOnly
	candidate.ExclusionReason = row.ExclusionReason
}

func applyRouteSnapshotEvidenceToStatus(candidate *RouteCandidateStatus, row modelsnapshot.KnownModel) {
	if candidate == nil {
		return
	}
	candidate.SourceStatus = string(row.Status)
	candidate.AutoRoutable = row.AutoRoutable
	candidate.ExactPinOnly = row.ExactPinOnly
	candidate.ExclusionReason = row.ExclusionReason
	candidate.Power = row.Power
	candidate.ContextLength = row.ContextWindow
	candidate.CostInputPerMTok = row.CostInputPerM
	candidate.CostOutputPerMTok = row.CostOutputPerM
	candidate.RecentLatencyMS = float64(row.RecentP50Latency.Milliseconds())
	candidate.QuotaRemaining = row.QuotaRemaining
}

func (s *service) annotateRouteDecisionSnapshotEvidence(decision *RouteDecision, snapshot modelsnapshot.ModelSnapshot) {
	if s == nil || decision == nil {
		return
	}
	for i := range decision.Candidates {
		if row, ok := routeSnapshotEvidenceForCandidate(decision.Candidates[i], snapshot); ok {
			applyRouteSnapshotEvidence(&decision.Candidates[i], row)
		}
	}
}

func (s *service) annotateRouteDecisionEvidence(decision *RouteDecision) {
	if s == nil || decision == nil {
		return
	}
	decision.Utilization = s.routeUtilizationEvidence(decision.Provider, decision.ServerInstance, decision.Endpoint, decision.Model)
	for i := range decision.Candidates {
		decision.Candidates[i].Utilization = s.routeUtilizationEvidence(
			decision.Candidates[i].Provider,
			decision.Candidates[i].ServerInstance,
			decision.Candidates[i].Endpoint,
			decision.Candidates[i].Model,
		)
	}
}

func (s *service) routeUtilizationEvidence(provider, serverInstance, endpoint, model string) RouteUtilizationState {
	if s == nil || s.routeUtilization == nil {
		return RouteUtilizationState{}
	}
	keyProvider := strings.TrimSpace(provider)
	keyServerInstance := strings.TrimSpace(serverInstance)
	keyEndpoint := strings.TrimSpace(endpoint)
	if base, ep, ok := splitEndpointProviderRef(keyProvider); ok {
		keyProvider = base
		if keyEndpoint == "" {
			keyEndpoint = ep
		}
	}
	if keyServerInstance == "" {
		keyServerInstance = keyEndpoint
	}
	sample, ok := s.routeUtilization.Sample(keyProvider, keyServerInstance, model)
	if !ok && keyEndpoint != "" && keyEndpoint != keyServerInstance {
		sample, ok = s.routeUtilization.Sample(keyProvider, keyEndpoint, model)
	}
	if !ok {
		return RouteUtilizationState{}
	}
	return routeUtilizationStateFromSample(sample)
}

func routeUtilizationStateFromSample(sample utilization.EndpointUtilization) RouteUtilizationState {
	out := RouteUtilizationState{
		Source:     string(sample.Source),
		Freshness:  string(sample.Freshness),
		ObservedAt: sample.ObservedAt,
	}
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	if sample.CacheUsage != nil {
		v := *sample.CacheUsage
		out.CachePressure = &v
	}
	if out.CachePressure == nil && sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := 0
		if sample.ActiveRequests != nil {
			total += *sample.ActiveRequests
		}
		if sample.QueuedRequests != nil {
			total += *sample.QueuedRequests
		}
		pressure := float64(total) / float64(*sample.MaxConcurrency)
		out.CachePressure = &pressure
	}
	return out
}

// publicFilterReason maps the typed FilterReason emitted by the internal
// routing engine to the public FilterReason* string constant. The internal
// constants are defined to share string values with the public surface, so
// this is a one-line passthrough — there is no string parsing.
func publicFilterReason(c routing.Candidate) string {
	if c.Eligible {
		return ""
	}
	return string(c.FilterReason)
}

// capabilityScoreForCostClass maps the harness cost class to a coarse
// numeric capability proxy. Mirrors the engine's costClassRank ordering
// (more expensive ≈ more capable) for reporting purposes only.
func capabilityScoreForCostClass(class string) float64 {
	switch class {
	case "local":
		return 0
	case "cheap":
		return 1
	case "medium", "":
		return 2
	case "expensive":
		return 3
	case "experimental":
		return -1
	default:
		return 0
	}
}

// escalatePolicyLadder walks routing.PolicyEscalationLadder when Resolve
// returns a "no eligible candidate" error and the request's policy is in
// the ladder. Returns (true, decision, nil) when a higher tier resolves to
// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
// the entire remaining ladder is also empty. Returns (false, _, _) when
// escalation does not apply (hard pin error, policy not in ladder, etc.).
func escalatePolicyLadder(req routing.Request, in routing.Inputs, origErr error, displayPolicy string) (bool, *routing.Decision, error) {
	if origErr == nil || req.Policy == "" {
		return false, nil, nil
	}
	if !shouldEscalateOnError(origErr) {
		return false, nil, nil
	}
	startIdx := -1
	for i, p := range routing.PolicyEscalationLadder {
		if p == req.Policy {
			startIdx = i
			break
		}
	}
	if startIdx < 0 {
		return false, nil, nil
	}
	for i := startIdx + 1; i < len(routing.PolicyEscalationLadder); i++ {
		probe := req
		probe.Policy = routing.PolicyEscalationLadder[i]
		dec, err := routing.Resolve(probe, in)
		if err == nil && dec != nil && dec.Harness != "" {
			return true, dec, nil
		}
	}
	starting := displayPolicy
	if starting == "" {
		starting = req.Policy
	}
	return true, nil, &routing.ErrNoLiveProvider{
		PromptTokens:   req.EstimatedPromptTokens,
		RequiresTools:  req.RequiresTools,
		StartingPolicy: starting,
		MinPower:       req.MinPower,
		MaxPower:       req.MaxPower,
		AllowLocal:     req.AllowLocal,
	}
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/compaction"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modeleligibility"
	"github.com/easel/fizeau/internal/modelsnapshot"
	"github.com/easel/fizeau/internal/provider/utilization"
	"github.com/easel/fizeau/internal/routing"
	"github.com/easel/fizeau/internal/serverinstance"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// fiz-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	if req.Harness != "" && req.Model != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
			return nil, err
		}
	}
	if req.Harness != "" && req.Policy != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessPolicy(canonical, cfg, req.Policy); err != nil {
			return nil, err
		}
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	requestedPolicy := req.Policy
	policy := routingPolicyForName(cat, requestedPolicy)
	powerPolicy := routePowerPolicyForRequest(cat, req)
	providerPreference, err := providerPreferenceForPolicy(cat, requestedPolicy)
	if err != nil {
		return &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
		}, err
	}
	in, snapshot := s.buildRoutingInputsWithCatalog(ctx, cat)

	resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
	if modelErr != nil {
		result := &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
			Candidates:      modelCandidates,
		}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(modelErr, result.Candidates, req.Policy)
	}

	rReq := routing.Request{
		Policy:                policy,
		Model:                 resolvedModel,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		CorrelationID:         req.CorrelationID,
		AllowLocal:            req.AllowLocal,
		Require:               append([]string(nil), req.Require...),
	}
	if policyEntry, _, ok := policyForName(cat, requestedPolicy); ok {
		rReq.AllowLocal = rReq.AllowLocal || policyEntry.AllowLocal
		rReq.Require = append(append([]string(nil), policyEntry.Require...), rReq.Require...)
	}
	rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalatePolicyLadder(rReq, in, err, req.Policy); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec, powerPolicy)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		result.RequestedPolicy = req.Policy
		result.PowerPolicy = powerPolicy
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(err, result.Candidates, req.Policy)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	if result != nil && result.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(result.Provider)
		result.Endpoint = endpoint
	}
	s.annotateRouteDecisionSnapshotEvidence(result, snapshot)
	s.annotateRouteDecisionEvidence(result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.RequestedPolicy = req.Policy
		result.PowerPolicy = powerPolicy
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision, powerPolicy RoutePowerPolicy) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:        dec.Harness,
		Provider:       dec.Provider,
		Endpoint:       dec.Endpoint,
		ServerInstance: dec.ServerInstance,
		Model:          dec.Model,
		Reason:         dec.Reason,
		Candidates:     routeCandidatesFromInternal(dec.Candidates, powerPolicy),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate, powerPolicy RoutePowerPolicy) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate, powerPolicy)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate, powerPolicy RoutePowerPolicy) RouteCandidate {
	components := RouteCandidateComponents{
		Power:            candidate.Power,
		Cost:             candidate.CostUSDPer1kTokens,
		CostClass:        candidate.CostClass,
		LatencyMS:        candidate.LatencyMS,
		SpeedTPS:         candidate.SpeedTPS,
		Utilization:      candidate.Utilization,
		SuccessRate:      candidate.SuccessRate,
		QuotaOK:          candidate.QuotaOK,
		QuotaPercentUsed: candidate.QuotaPercentUsed,
		QuotaTrend:       candidate.QuotaTrend,
		Capability:       capabilityScoreForCostClass(candidate.CostClass),
		ContextHeadroom:  candidate.ContextHeadroom,
		StickyAffinity:   candidate.StickyAffinity,
	}
	powerHintFit := scorePowerHintFit(candidate.Power, powerPolicy)
	scorePower := candidate.ScoreComponents["power"]
	scoreCost := candidate.ScoreComponents["cost"]
	scorePerformance := candidate.ScoreComponents["performance"]
	scoreLocality := candidate.ScoreComponents["deployment_locality"]
	scoreQuota := candidate.ScoreComponents["quota_health"]
	scoreUtilization := candidate.ScoreComponents["utilization"]
	components.PowerHintFit = powerHintFit
	components.PowerWeightedCapability = scorePower - powerHintFit + positiveScorePart(scoreCost)
	components.LatencyWeight = positiveScorePart(scorePerformance)
	components.StaleSignalPenalty = positiveScorePart(-scorePerformance)
	components.PlacementBonus = scoreLocality + candidate.StickyAffinity
	components.QuotaBonus = positiveScorePart(scoreQuota)
	components.MarginalCostPenalty = positiveScorePart(-scoreCost)
	components.AvailabilityPenalty = positiveScorePart(-scoreQuota) + positiveScorePart(-scoreUtilization)
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Billing:            candidate.Billing,
		Endpoint:           candidate.Endpoint,
		ServerInstance:     candidate.ServerInstance,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		ContextLength:      candidate.ContextLength,
		ContextSource:      candidate.ContextSource,
		Components:         components,
	}
}

func scorePowerHintFit(power int, policy RoutePowerPolicy) float64 {
	if power <= 0 {
		return 0
	}
	if policy.MinPower > 0 && power < policy.MinPower {
		// Mirror the engine scorer: materially underpowered routes should not
		// win just because they are cheap.
		return -float64(policy.MinPower-power) * 12
	}
	if policy.MaxPower > 0 && power > policy.MaxPower {
		return -float64(power - policy.MaxPower)
	}
	return 0
}

func positiveScorePart(v float64) float64 {
	if v > 0 {
		return v
	}
	return 0
}

type routeSnapshotCandidateKey struct {
	Provider       string
	Endpoint       string
	ServerInstance string

// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
// ErrPolicyRequirementUnsatisfied) are surfaced as-is — escalating past an explicit
// pin would silently change the caller's intent.
func shouldEscalateOnError(err error) bool {
	var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
	if errors.As(err, &modelConstraintAmbiguous) {
		return false
	}
	var modelConstraintNoMatch *ErrModelConstraintNoMatch
	if errors.As(err, &modelConstraintNoMatch) {
		return false
	}
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return false
	}
	var pinErr *routing.ErrUnsatisfiablePin
	if errors.As(err, &pinErr) {
		return false
	}
	var policyErr *routing.ErrPolicyRequirementUnsatisfied
	if errors.As(err, &policyErr) {
		return false
	}
	return true
}

func publicRoutingError(err error, candidates []RouteCandidate, requestedPolicy ...string) error {
	displayPolicy := func(policy string) string {
		if len(requestedPolicy) > 0 && requestedPolicy[0] != "" {
			return requestedPolicy[0]
		}
		return policy
	}
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return withRouteCandidates(&ErrHarnessModelIncompatible{
			Harness:         modelErr.Harness,
			Model:           modelErr.Model,
			SupportedModels: append([]string(nil), modelErr.SupportedModels...),
		}, candidates)
	}
	var policyErr *routing.ErrPolicyRequirementUnsatisfied
	if errors.As(err, &policyErr) {
		return withRouteCandidates(&ErrPolicyRequirementUnsatisfied{
			Policy:       displayPolicy(policyErr.Policy),
			Requirement:  policyErr.Requirement,
			AttemptedPin: policyErr.AttemptedPin,
			Rejected:     policyErr.Rejected,
		}, candidates)
	}
	var unknownPolicyErr *routing.ErrUnknownPolicy
	if errors.As(err, &unknownPolicyErr) {
		return withRouteCandidates(&ErrUnknownPolicy{
			Policy: displayPolicy(unknownPolicyErr.Policy),
		}, candidates)
	}
	var pinErr *routing.ErrUnsatisfiablePin
	if errors.As(err, &pinErr) {
		return withRouteCandidates(&ErrUnsatisfiablePin{
			Pin:    pinErr.Pin,
			Reason: pinErr.Reason,
		}, candidates)
	}
	var noLiveErr *routing.ErrNoLiveProvider
	if errors.As(err, &noLiveErr) {
		return withRouteCandidates(&ErrNoLiveProvider{
			PromptTokens:   noLiveErr.PromptTokens,
			RequiresTools:  noLiveErr.RequiresTools,
			StartingPolicy: displayPolicy(noLiveErr.StartingPolicy),
		}, candidates)
	}
	var quotaErr *routing.ErrAllProvidersQuotaExhausted
	if errors.As(err, &quotaErr) {
		return withRouteCandidates(&NoViableProviderForNow{
			RetryAfter:         quotaErr.RetryAfter,
			ExhaustedProviders: append([]string(nil), quotaErr.ExhaustedProviders...),
		}, candidates)
	}
	return withRouteCandidates(err, candidates)
}

func withRouteCandidates(err error, candidates []RouteCandidate) error {
	if err == nil || len(candidates) == 0 {
		return err
	}
	return &routeDecisionError{
		err:        err,
		candidates: append([]RouteCandidate(nil), candidates...),
	}
}

func (s *service) applyRouteAttemptCooldowns(in *routing.Inputs) {
	if in == nil {
		return
	}
	ttl := s.routeAttemptTTL()
	records := s.activeRouteAttempts(time.Now(), ttl)
	if len(records) == 0 {
		return
	}
	if in.ProviderCooldowns == nil {
		in.ProviderCooldowns = make(map[string]time.Time)
	}
	if in.CooldownDuration <= 0 {
		in.CooldownDuration = ttl
	}
	for _, record := range records {
		if record.Key.Provider != "" {
			existing, ok := in.ProviderCooldowns[record.Key.Provider]
			if !ok || record.RecordedAt.After(existing) {
				in.ProviderCooldowns[record.Key.Provider] = record.RecordedAt
			}
		}
		if record.Key.Provider == "" && record.Key.Harness != "" {
			for i := range in.Harnesses {
				if in.Harnesses[i].Name == record.Key.Harness {
					in.Harnesses[i].InCooldown = true
				}
			}
		}
	}
}

func (s *service) routeAttemptTTL() time.Duration {
	if s.opts.ServiceConfig == nil {
		return defaultRouteAttemptCooldown
	}
	ttl := s.opts.ServiceConfig.HealthCooldown()
	if ttl <= 0 {
		return defaultRouteAttemptCooldown
	}
	return ttl
}

// buildRoutingInputs assembles routing.Inputs from the service's registry
// and snapshot-derived provider inventory. The public routing engine stays
// unchanged; only the source of provider/model candidates changes.
func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
	inputs, _ := s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog())
	return inputs
}

func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) (routing.Inputs, modelsnapshot.ModelSnapshot) {
	statuses := s.registry.Discover()
	statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
	for _, st := range statuses {
		statusByName[st.Name] = st
	}
	now := time.Now().UTC()
	var snapshot modelsnapshot.ModelSnapshot
	if s.opts.ServiceConfig != nil {
		if cacheRoot, err := serviceSnapshotCacheRoot(); err == nil {
			snapshot, _ = assembleModelSnapshotFromServiceConfigWithOptions(
				ctx,
				s.opts.ServiceConfig,
				cat,
				cacheRoot,
				modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshBackground},
			)
		}
	}

	var entries []routing.HarnessEntry
	for _, name := range s.registry.Names() {
		cfg, ok := s.registry.Get(name)
		if !ok {
			continue
		}
		st := statusByName[name]
		entry := routingHarnessEntryFromMetadata(name, cfg, st)
		if name == "fiz" && s.opts.ServiceConfig == nil {
			entry.AutoRoutingEligible = false
		}

		if qs, ok := subscriptionQuotaForHarness(name, time.Now()); ok {
			entry.QuotaOK = qs.OK
			entry.QuotaStale = qs.Present && !qs.Fresh
			entry.SubscriptionOK = qs.OK
			entry.QuotaPercentUsed = qs.PercentUsed
			entry.QuotaTrend = qs.Trend
			entry.QuotaReason = qs.Reason
		}

		// Native "fiz" harness: enumerate snapshot-derived provider rows.
		if name == "fiz" && s.opts.ServiceConfig != nil {
			entry.Providers = s.snapshotProviderEntries(ctx, cat, snapshot)
			// Tool support for the agent harness is per-(provider, model);
			// the harness-level baseline is whether ANY provider supports
			// tools. Engine OR-combines harness and provider SupportsTools
			// so this lets a per-model no_tools catalog flag actually fire
			// the RequiresTools gate when every provider's resolved model
			// is no-tools.
			if len(entry.Providers) > 0 {
				entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
			} else {
				entry.Available = false
			}
		}
		s.applySubscriptionRoutingCost(&entry, cat)
		entries = append(entries, entry)
	}
	successRate, latencyMS := s.routeMetricSignals(now, s.routeAttemptTTL())
	return routing.Inputs{
		Harnesses:                    entries,
		ProviderSuccessRate:          successRate,
		ObservedLatencyMS:            latencyMS,
		ProviderQuotaExhaustedUntil:  s.providerQuotaExhaustedUntil(now),
		ModelEligibility:             serviceRoutingModelEligibility(entries, cat),
		ReasoningResolver:            serviceRoutingReasoningResolver(cat),
		EndpointLoadResolver:         s.routeEndpointLoadsResolver(now),
		StickyServerInstanceResolver: s.routeStickyServerInstanceResolver(now),
	}, snapshot
}

func (s *service) snapshotProviderEntries(ctx context.Context, cat *modelcatalog.Catalog, snapshot modelsnapshot.ModelSnapshot) []routing.ProviderEntry {
	if s == nil || s.opts.ServiceConfig == nil {
		return nil
	}
	providerNames := s.opts.ServiceConfig.ProviderNames()
	if len(providerNames) == 0 || len(snapshot.Models) == 0 {
		return nil
	}
	grouped := make(map[snapshotProviderGroupKey][]modelsnapshot.KnownModel)
	for _, row := range snapshot.Models {
		harness := strings.TrimSpace(row.Harness)
		if harness != "" && harness != "fiz" {
			continue
		}
		providerName := strings.TrimSpace(row.Provider)
		if providerName == "" {
			continue
		}
		if _, ok := s.opts.ServiceConfig.Provider(providerName); !ok {
			continue
		}
		key := snapshotProviderGroupKey{
			Provider:        providerName,
			EndpointName:    strings.TrimSpace(row.EndpointName),

			EndpointName:    strings.TrimSpace(row.EndpointName),
			EndpointBaseURL: strings.TrimSpace(row.EndpointBaseURL),
			ServerInstance:  strings.TrimSpace(row.ServerInstance),
		}
		grouped[key] = append(grouped[key], row)
	}
	if len(grouped) == 0 {
		return nil
	}

	groupCountByProvider := make(map[string]int)
	for key := range grouped {
		groupCountByProvider[key.Provider]++
	}

	keys := make([]snapshotProviderGroupKey, 0, len(grouped))
	for key := range grouped {
		keys = append(keys, key)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].Provider != keys[j].Provider {
			return keys[i].Provider < keys[j].Provider
		}
		if keys[i].EndpointName != keys[j].EndpointName {
			return keys[i].EndpointName < keys[j].EndpointName
		}
		if keys[i].EndpointBaseURL != keys[j].EndpointBaseURL {
			return keys[i].EndpointBaseURL < keys[j].EndpointBaseURL
		}
		return keys[i].ServerInstance < keys[j].ServerInstance
	})

	var entries []routing.ProviderEntry
	for _, key := range keys {
		pcfg, ok := s.opts.ServiceConfig.Provider(key.Provider)
		if !ok || pcfg.ConfigError != "" {
			continue
		}
		rows := append([]modelsnapshot.KnownModel(nil), grouped[key]...)
		sort.Slice(rows, func(i, j int) bool {
			if rows[i].EndpointName != rows[j].EndpointName {
				return rows[i].EndpointName < rows[j].EndpointName
			}
			if rows[i].EndpointBaseURL != rows[j].EndpointBaseURL {
				return rows[i].EndpointBaseURL < rows[j].EndpointBaseURL
			}
			if rows[i].ServerInstance != rows[j].ServerInstance {
				return rows[i].ServerInstance < rows[j].ServerInstance
			}
			return rows[i].ID < rows[j].ID
		})
		discoveredIDs := snapshotModelIDs(rows)
		if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
			discoveredIDs = appendUniqueModelIDs(discoveredIDs, defaultModel)
		}
		ctxWindows, ctxSources := snapshotProviderContextWindows(ctx, pcfg, cat, rows, discoveredIDs)
		endpointName := snapshotEndpointName(pcfg, key)
		routeName := key.Provider
		if groupCountByProvider[key.Provider] > 1 {
			switch {
			case endpointName != "":
				routeName = endpointProviderRef(key.Provider, endpointName)
			case key.ServerInstance != "":
				routeName = endpointProviderRef(key.Provider, key.ServerInstance)
			case key.EndpointBaseURL != "":
				routeName = endpointProviderRef(key.Provider, key.EndpointBaseURL)
			}
		}
		baseURL := key.EndpointBaseURL
		if baseURL == "" {
			baseURL = pcfg.BaseURL
		}
		serverInstance := key.ServerInstance
		if serverInstance == "" {
			serverInstance = pcfg.ServerInstance
		}
		serverInstance = serverinstance.Normalize(baseURL, serverInstance)
		entry := routing.ProviderEntry{
			Name:                      routeName,
			BaseURL:                   baseURL,
			ServerInstance:            serverInstance,
			EndpointName:              endpointName,
			EndpointBaseURL:           baseURL,
			DefaultModel:              pcfg.Model,
			Billing:                   pcfg.Billing,
			CostClass:                 providerRoutingCostClass(pcfg.Type),
			DiscoveredIDs:             discoveredIDs,
			DiscoveryAttempted:        true,
			ContextWindows:            ctxWindows,
			ContextWindowSources:      ctxSources,
			ContextWindow:             pcfg.ContextWindow,
			ContextWindowSource:       contextWindowSourceForProviderConfig(pcfg),
			SupportsTools:             providerSupportsTools(cat, pcfg.Model, discoveredIDs),
			ExcludeFromDefaultRouting: pcfg.IncludeByDefaultSet && !pcfg.IncludeByDefault,
		}
		s.applyEndpointRoutingCost(&entry, pcfg, cat)
		entries = append(entries, entry)
	}
	return entries
}

type snapshotProviderGroupKey struct {
	Provider        string
	EndpointName    string
	EndpointBaseURL string
	ServerInstance  string
}

func snapshotEndpointName(pcfg ServiceProviderEntry, key snapshotProviderGroupKey) string {
	endpoints := modelDiscoveryEndpoints(pcfg)
	trimmedEndpointName := strings.TrimSpace(key.EndpointName)
	trimmedBaseURL := strings.TrimSpace(key.EndpointBaseURL)
	trimmedServerInstance := strings.TrimSpace(key.ServerInstance)
	if len(endpoints) == 0 {
		if trimmedEndpointName != "" {
			if strings.EqualFold(trimmedEndpointName, strings.TrimSpace(key.Provider)) {
				return "default"
			}
			return trimmedEndpointName
		}
		if trimmedServerInstance != "" {
			return trimmedServerInstance
		}
		if trimmedBaseURL != "" {
			return trimmedBaseURL
		}
		return ""
	}
	for _, endpoint := range endpoints {
		if trimmedEndpointName != "" && strings.EqualFold(endpoint.Name, trimmedEndpointName) {
			return endpoint.Name
		}
		if trimmedBaseURL != "" && strings.TrimSpace(endpoint.BaseURL) == trimmedBaseURL {
			return endpoint.Name
		}
		if trimmedServerInstance != "" && strings.TrimSpace(endpoint.ServerInstance) == trimmedServerInstance {
			return endpoint.Name
		}
	}
	if len(endpoints) == 1 {
		return endpoints[0].Name
	}
	if trimmedEndpointName != "" {
		return trimmedEndpointName
	}
	if trimmedServerInstance != "" {
		return trimmedServerInstance
	}
	if trimmedBaseURL != "" {
		return trimmedBaseURL
	}
	return ""
}

func snapshotModelIDs(rows []modelsnapshot.KnownModel) []string {
	if len(rows) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(rows))
	ids := make([]string, 0, len(rows))
	for _, row := range rows {
		id := strings.TrimSpace(row.ID)
		if id == "" {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

func snapshotProviderContextWindows(ctx context.Context, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog, rows []modelsnapshot.KnownModel, discoveredIDs []string) (map[string]int, map[string]string) {
	_ = ctx
	out := make(map[string]int)
	sources := make(map[string]string)
	rowByID := make(map[string]modelsnapshot.KnownModel, len(rows))
	for _, row := range rows {
		id := strings.TrimSpace(row.ID)
		if id == "" {
			continue
		}
		if _, exists := rowByID[id]; !exists {
			rowByID[id] = row
		}
	}
	add := func(modelID string, snapshotWindow int) {
		modelID = strings.TrimSpace(modelID)
		if modelID == "" {
			return
		}
		window, source := snapshotContextWindow(pcfg, cat, modelID, snapshotWindow)
		if window <= 0 {
			return
		}
		out[modelID] = window
		sources[modelID] = source
	}
	if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
		row, ok := rowByID[defaultModel]
		if ok {
			add(defaultModel, row.ContextWindow)
		} else {
			add(defaultModel, 0)
		}
	}
	for _, id := range discoveredIDs {
		row, ok := rowByID[id]
		if ok {
			add(id, row.ContextWindow)
			continue
		}
		add(id, 0)
	}
	if len(out) == 0 {
		return nil, nil
	}
	return out, sources
}

func snapshotContextWindow(pcfg ServiceProviderEntry, cat *modelcatalog.Catalog, modelID string, snapshotWindow int) (int, string) {
	if pcfg.ContextWindow > 0 {
		return pcfg.ContextWindow, ContextSourceProviderConfig
	}
	if snapshotWindow > 0 {
		return snapshotWindow, ContextSourceCatalog
	}
	if cat != nil {
		if n := cat.ContextWindowForModel(modelID); n > 0 {
			return n, ContextSourceCatalog
		}
	}
	return compaction.DefaultContextWindow, ContextSourceDefault
}

// providerQuotaExhaustedUntil snapshots the per-provider quota state machine
// at the given instant for the routing engine. Returns nil when no provider
// is currently in quota_exhausted state, which keeps the routing path
// allocation-free in the common case.
func (s *service) providerQuotaExhaustedUntil(now time.Time) map[string]time.Time {
	if s == nil || s.providerQuota == nil {
		return nil
	}
	return s.providerQuota.ExhaustedAt(now)
}

// startQuotaRecoveryProbeLoop spawns the goroutine that periodically probes
// quota_exhausted providers and either restores them to available or extends
// their retry_after with bounded backoff. The goroutine is tied to
// QuotaRefreshContext (or context.Background()) so server callers can cancel
// it on shutdown.
func (s *service) startQuotaRecoveryProbeLoop() {
	if s == nil || s.providerQuota == nil {
		return
	}
	ctx := s.opts.QuotaRefreshContext
	if ctx == nil {
		ctx = context.Background()
	}
	probe := s.quotaRecoveryProber()
	if probe == nil {
		return
	}
	go runQuotaRecoveryProbeLoop(ctx, s.providerQuota, probe, defaultQuotaRecoveryFallbackInterval, nil, nil)
}

// quotaRecoveryProber returns the QuotaRecoveryProber used by the recovery
// loop. It looks up the provider entry in ServiceConfig and reuses the same
// probeProviderStatus the HealthCheck endpoint uses; a "connected" status
// counts as recovery, anything else is reported as a probe failure so the
// retry_after gets extended with backoff.
func (s *service) quotaRecoveryProber() QuotaRecoveryProber {
	sc := s.opts.ServiceConfig
	if sc == nil {
		return nil
	}
	return func(ctx context.Context, name string) error {
		entry, ok := sc.Provider(name)
		if !ok {
			return fmt.Errorf("provider %q not found", name)
		}
		probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
		if probe.status == "connected" {
			return nil
		}
		if probe.detail != "" {
			return fmt.Errorf("%s", probe.detail)
		}
		return fmt.Errorf("%s", probe.status)
	}
}

// ProviderQuotaState returns the per-provider quota state machine for this
// service. Callers (notably the quota-signal ingest path defined in sibling
// beads) drive transitions via MarkQuotaExhausted / MarkAvailable.
func (s *service) ProviderQuotaState() *ProviderQuotaStateStore {
	if s == nil {
		return nil
	}
	return s.providerQuota
}

func serviceRoutingCatalog() *modelcatalog.Catalog {
	cat, err := loadRoutingCatalog()
	if err != nil || cat == nil {
		return nil
	}
	return cat
}

func routingPolicyForName(cat *modelcatalog.Catalog, name string) string {
	name = strings.TrimSpace(name)
	switch name {
	case "":
		return ""
	case "cheap", "default", "smart", "air-gapped":
		return name
	}
	if cat == nil {
		return name
	}
	_, policyName, ok := policyForName(cat, name)
	if !ok {
		return name
	}
	switch policyName {
	case "smart":
		return "smart"
	case "default":
		return "default"
	case "cheap":
		return "cheap"
	default:
		return policyName
	}
}

func serviceRoutingCatalogResolver(cat *modelcatalog.Catalog) func(ref, surface string) (string, bool) {
	if cat == nil {
		return nil
	}
	return func(ref, surface string) (string, bool) {
		catalogSurface, ok := serviceRoutingCatalogSurface(surface)
		if !ok {
			return "", false
		}
		resolved, err := cat.Resolve(ref, modelcatalog.ResolveOptions{
			Surface:         catalogSurface,
			AllowDeprecated: true,
		})
		if err != nil || resolved.ConcreteModel == "" {
			return "", false
		}
		return resolved.ConcreteModel, true
	}
}

package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

// Request is the routing input. All fields are optional except at least
// one of {Policy, Model, Harness, Provider} should be set (otherwise the
// engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Policy             string // "cheap" | "default" | "smart" | "air-gapped"
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"
	CorrelationID      string // validated sticky route key, when available
	AllowLocal         bool
	Require            []string

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"

	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "fiz" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name                 string
	BaseURL              string
	ServerInstance       string
	EndpointName         string
	EndpointBaseURL      string
	DefaultModel         string
	Billing              modelcatalog.BillingModel
	CostClass            string
	DiscoveredIDs        []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted   bool
	ContextWindows       map[string]int
	ContextWindowSources map[string]string
	ContextWindow        int
	ContextWindowSource  string
	SupportsTools        bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool

	// ExcludeFromDefaultRouting, when true, prevents this provider from being
	// selected during unpinned automatic routing. An explicit provider, harness,
	// or model pin bypasses this gate so the operator can still reach the
	// provider intentionally. Corresponds to IncludeByDefault=false in config.
	ExcludeFromDefaultRouting bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness        string
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
	Reason         string
	Candidates     []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Billing            modelcatalog.BillingModel
	Endpoint           string
	ServerInstance     string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	ContextLength      int
	ContextSource      string
	ScoreComponents    map[string]float64
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS       float64
	SuccessRate     float64
	CostClass       string
	SpeedTPS        float64
	Utilization     float64
	ContextHeadroom int

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
	StickyAffinity   float64
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
	// FilterReasonPolicyFiltered: candidate was rejected by a hard policy
	// requirement such as allow_local=false or require=[no_remote].

	// requirement such as allow_local=false or require=[no_remote].
	FilterReasonPolicyFiltered FilterReason = "policy_filtered"
	// FilterReasonProviderExcludedFromDefault: provider has IncludeByDefault=false
	// in operator config and the request did not explicitly pin a provider or harness.
	FilterReasonProviderExcludedFromDefault FilterReason = "provider_excluded_from_default_routing"
	// FilterReasonMeteredOptInRequired: pay-per-token candidate was removed
	// from unpinned automatic routing because metered spend was not enabled.
	FilterReasonMeteredOptInRequired FilterReason = "metered_opt_in_required"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)
	}
	return fmt.Sprintf("no viable routing candidate: %d candidates rejected", e.Rejected)
}

// CandidateRejectionReason is the stable reason vocabulary used when a policy
// matches candidates but every candidate is rejected before dispatch.
type CandidateRejectionReason string

const (
	CandidateRejectionQuotaExhausted   CandidateRejectionReason = "quota_exhausted"
	CandidateRejectionUnhealthy        CandidateRejectionReason = "unhealthy"
	CandidateRejectionModelUnavailable CandidateRejectionReason = "model_unavailable"
	CandidateRejectionHarnessUnhealthy CandidateRejectionReason = "harness_unhealthy"
	CandidateRejectionPolicyFiltered   CandidateRejectionReason = "policy_filtered"
)

// CandidateRejection records why a matching candidate could not be used.
type CandidateRejection struct {
	Provider string
	Harness  string
	Model    string
	Reason   string
}

// ErrNoLiveProvider reports that policy escalation walked the entire ladder
// (cheap → default → smart) without finding a live provider that
// can serve the request. Callers translate this into a precise user-facing
// message naming the prompt size and tool requirement so operators know
// what capability is missing across all policies.
type ErrNoLiveProvider struct {
	// PromptTokens is the request's EstimatedPromptTokens at the time
	// escalation began. Zero means no prompt-token gating was active.
	PromptTokens int
	// RequiresTools mirrors the request's RequiresTools flag.
	RequiresTools bool
	// StartingPolicy is the policy name that escalation began from.
	StartingPolicy     string
	MinPower           int
	MaxPower           int
	AllowLocal         bool
	RejectedCandidates []CandidateRejection
}

func (e *ErrNoLiveProvider) Error() string {
	if len(e.RejectedCandidates) == 0 {
		return fmt.Sprintf("no candidates match policy %q (power %d-%d, allow_local=%v); check policy fit and provider configuration",
			e.StartingPolicy, e.MinPower, e.MaxPower, e.AllowLocal)
	}
	counts := map[string]int{}
	for _, rejected := range e.RejectedCandidates {
		counts[rejected.Reason]++
	}
	return fmt.Sprintf("policy %q has %d candidate(s) matching power %d-%d but all rejected: %d quota-exhausted, %d unhealthy, %d unavailable",
		e.StartingPolicy,
		len(e.RejectedCandidates),
		e.MinPower,
		e.MaxPower,
		counts[string(CandidateRejectionQuotaExhausted)],
		counts[string(CandidateRejectionUnhealthy)]+counts[string(CandidateRejectionHarnessUnhealthy)],
		counts[string(CandidateRejectionModelUnavailable)])
}

// PolicyEscalationLadder is the fixed cheap → default → smart progression
// service.ResolveRoute walks when every candidate at the requested tier is
// filtered out (unhealthy or capability-rejected).
var PolicyEscalationLadder = []string{"cheap", "default", "smart"}

// Inputs bundles the engine's external data sources.
type Inputs struct {
	Harnesses                    []HarnessEntry
	HistoricalSuccess            map[string]float64 // by harness name; -1 = insufficient data
	ObservedSpeedTPS             map[string]float64 // by "provider:model"
	ProviderSuccessRate          map[string]float64 // by ProviderModelKey(provider, endpoint, model)
	ObservedLatencyMS            map[string]float64 // by ProviderModelKey(provider, endpoint, model)
	EndpointLoads                map[string]EndpointLoad
	EndpointLoadResolver         func(provider, endpoint, model string) (EndpointLoad, bool)
	StickyServerInstanceResolver func(stickyKey string) (string, bool)
	ProviderCooldowns            map[string]time.Time // by provider name
	CooldownDuration             time.Duration        // 0 = no cooldown enforcement

	// ProviderQuotaExhaustedUntil maps provider name → retry_after time.
	// A provider with retry_after > Now is treated as quota_exhausted and
	// disqualified from candidate selection. The service maintains the
	// per-provider quota state machine and projects it into this map for
	// each routing call.
	ProviderQuotaExhaustedUntil map[string]time.Time
	Now                         time.Time // injected for deterministic testing; default time.Now()
	ModelEligibility            func(model string) (ModelEligibility, bool)

	// ReasoningResolver returns the catalog's reasoning default for a
	// (policy, surface) pair. When set, buildHarnessCandidates uses it
	// to resolve Reasoning=auto to a concrete level before invoking the
	// capability gate, so candidates that cannot satisfy the resolved level
	// (e.g. an off-only variant under a policy whose default is
	// "high") are correctly disqualified instead of slipping through.
	ReasoningResolver func(policy, surface string) (resolved string, ok bool)
}

// EndpointLoad is the routing engine's normalized view of endpoint load for a
// single provider/model tuple.
type EndpointLoad struct {
	LeaseCount           int
	NormalizedLoad       float64
	UtilizationFresh     bool
	UtilizationSaturated bool
}

// ModelEligibility is the routing engine's catalog-power view for one model.
// Unknown or zero-power models are still usable through exact Model pins, but
// are excluded from unpinned automatic routing.
type ModelEligibility struct {
	Power        int
	ExactPinOnly bool
	AutoRoutable bool
}

// candidateInternal carries the engine's intermediate state per (harness, provider, model).
type candidateInternal struct {
	Harness               string
	Provider              string
	Billing               modelcatalog.BillingModel
	EndpointName          string
	ServerInstance        string
	Model                 string
	CostClass             string
	CostUSDPer1kTokens    float64
	CostSource            string
	Power                 int
	ContextLength         int
	ContextSource         string
	ContextHeadroom       int
	IsSubscription        bool
	QuotaOK               bool
	QuotaPercentUsed      int
	QuotaStale            bool
	QuotaTrend            string
	SubscriptionOK        bool
	HistoricalSuccessRate float64
	ProviderSuccessRate   float64
	ObservedTokensPerSec  float64
	ObservedLatencyMS     float64
	InCooldown            bool
	ProviderAffinityMatch bool
	ProviderPreference    string
	EndpointLoad          float64
	EndpointLoadFresh     bool
	EndpointSaturated     bool
	StickyMatch           bool
	MinPower              int
	MaxPower              int
}

// ProviderModelKey is the metrics key used by routing callers for provider
// performance signals. Endpoint is optional; when empty the key remains
// compatible with older provider:model metrics.
func ProviderModelKey(provider, endpoint, model string) string {
	if endpoint == "" {
		return provider + ":" + model
	}
	return provider + "@" + endpoint + ":" + model
}

// Resolve runs the engine end-to-end and returns a Decision.
//
// The engine:
//  1. Enumerates (harness, provider, model) candidates from inputs.
//  2. Applies gating (capability, override, model-pin, surface).
//  3. Scores per policy with cooldown demotion + perf bias.
//  4. Sorts viable → score → cost → locality → name.
//  5. Returns the top viable candidate with the full ranked list.
//
// Returns an error only when no viable candidate exists.
func Resolve(req Request, in Inputs) (*Decision, error) {
	if in.Now.IsZero() {
		in.Now = time.Now()
	}
	policyName, err := canonicalPolicy(req.Policy)
	if err != nil {
		return &Decision{}, err
	}
	req.Policy = policyName
	if err := validateRequirements(req); err != nil {
		return &Decision{}, err
	}

	canonicalHarness := req.Harness
	if canonicalHarness == "local" {
		canonicalHarness = "fiz"
	}
	if err := explicitPinError(req, in); err != nil {
		return &Decision{}, err
	}

	var ranked []rankedCandidate
	for _, h := range in.Harnesses {
		// TestOnly harnesses (script/virtual) only reachable via explicit override.
		if h.TestOnly && canonicalHarness != h.Name {
			continue
		}
		// Automatic profile/tier routing is restricted to harnesses with full
		// coverage. Explicit Harness pins can still use experimental/ad-hoc
		// harnesses.
		if canonicalHarness == "" && !h.AutoRoutingEligible {
			continue
		}
		// Hard harness override: skip non-matching harnesses.
		if canonicalHarness != "" && canonicalHarness != h.Name {
			continue
		}
		entries := buildHarnessCandidates(h, req, in)
		ranked = append(ranked, entries...)
	}

	// Compute scores only after eligibility is final. Rejected candidates keep
	// a zero score because cost/utilization/performance/sticky ranking should
	// never influence the eligibility boundary.
	for i := range ranked {
		if !ranked[i].out.Eligible {
			continue
		}
		ranked[i].out.Score = scorePolicy(req.Policy, ranked[i].internal)
		ranked[i].out.ScoreComponents = scoreComponents(req.Policy, ranked[i].internal)
		ranked[i].out.Reason = fmt.Sprintf("policy=%s; score=%.1f", req.Policy, ranked[i].out.Score)
	}
	neutralCost, hasKnownCost := neutralKnownCost(ranked)

	// Sort: eligible first, then descending score, then cost, then locality,
	// then alphabetical.
	sort.SliceStable(ranked, func(i, j int) bool {
		ei, ej := ranked[i].out.Eligible, ranked[j].out.Eligible
		if ei != ej {
			return ei
		}
		if !ei {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		if ranked[i].out.Score != ranked[j].out.Score {
			return ranked[i].out.Score > ranked[j].out.Score
		}
		if hasKnownCost {
			ci := candidateCostTieValue(ranked[i], neutralCost)
			cj := candidateCostTieValue(ranked[j], neutralCost)
			if ci != cj {
				return ci < cj
			}
		}
		// Locality tiebreak: prefer local cost-class.
		li := costClassRank[ranked[i].internal.CostClass] == 0
		lj := costClassRank[ranked[j].internal.CostClass] == 0
		if li != lj {
			return li
		}
		if sameLocalEndpointGroup(ranked[i].internal, ranked[j].internal) {
			if ranked[i].internal.EndpointSaturated != ranked[j].internal.EndpointSaturated {
				return !ranked[i].internal.EndpointSaturated
			}
			if ranked[i].internal.EndpointLoad != ranked[j].internal.EndpointLoad {
				return ranked[i].internal.EndpointLoad < ranked[j].internal.EndpointLoad
			}
		}
		if ranked[i].out.Harness != ranked[j].out.Harness {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		return ranked[i].out.Provider < ranked[j].out.Provider
	})

	out := make([]Candidate, len(ranked))
	for i := range ranked {
		out[i] = ranked[i].out
	}

	for i := range out {
		if out[i].Eligible {
			return &Decision{
				Harness:        out[i].Harness,
				Provider:       out[i].Provider,
				Endpoint:       out[i].Endpoint,
				ServerInstance: out[i].ServerInstance,
				Model:          out[i].Model,
				Reason:         fmt.Sprintf("policy=%s; score=%.1f", req.Policy, out[i].Score),
				Candidates:     out,
			}, nil
		}
	}
	if quotaErr := allProvidersQuotaExhaustedError(ranked); quotaErr != nil {
		return &Decision{Candidates: out}, quotaErr
	}
	if requested := requestedModelIntent(req); requested != "" && req.Provider == "" && canonicalHarness == "" && hasLiveDiscoveryCandidates(ranked) {
		return &Decision{Candidates: out}, fmt.Errorf("no live endpoint offers a match for %s", requested)
	}
	if missingRequirement := missingPolicyRequirement(req, out); missingRequirement != "" {
		return &Decision{Candidates: out}, &ErrPolicyRequirementUnsatisfied{
			Policy:      req.Policy,
			Requirement: missingRequirement,
			Rejected:    len(out),
		}
	}
	return &Decision{Candidates: out}, noViableCandidateError(req, len(out))
}

// allProvidersQuotaExhaustedError returns ErrAllProvidersQuotaExhausted when
// at least one routing candidate was rejected solely because its provider is
// in the quota_exhausted state and no other candidate was eligible. The set
// of otherwise-eligible candidates collapses to those flagged with
// quotaExhaustedRetryAfter (the engine sets this only when the candidate
// passed every other gate). When that set is empty the existing
// no-viable / no-profile-candidate / live-discovery errors describe the
// failure more precisely.
func allProvidersQuotaExhaustedError(ranked []rankedCandidate) error {
	var exhausted []string
	seen := make(map[string]struct{})
	var earliest time.Time
	for _, c := range ranked {
		if c.quotaExhaustedRetryAfter.IsZero() {
			continue
		}
		name := c.out.Provider
		if name == "" {
			name = c.out.Harness
		}
		if _, dup := seen[name]; !dup {
			seen[name] = struct{}{}
			exhausted = append(exhausted, name)
		}
		if earliest.IsZero() || c.quotaExhaustedRetryAfter.Before(earliest) {
			earliest = c.quotaExhaustedRetryAfter
		}
	}
	if len(exhausted) == 0 {
		return nil
	}
	return &ErrAllProvidersQuotaExhausted{
		RetryAfter:         earliest,
		ExhaustedProviders: exhausted,
	}
}

func noViableCandidateError(req Request, rejected int) *NoViableCandidateError {
	return &NoViableCandidateError{
		Rejected: rejected,
		Model:    req.Model,
		Provider: req.Provider,
		Harness:  canonicalHarnessPin(req.Harness),
		MinPower: req.MinPower,
		MaxPower: req.MaxPower,
	}
}

func canonicalPolicy(policy string) (string, error) {
	if policy == "" {
		return "default", nil
	}
	switch policy {
	case "cheap", "default", "smart", "air-gapped":
		return policy, nil
	default:
		return "", &ErrUnknownPolicy{Policy: policy}
	}
}

func validateRequirements(req Request) error {
	for _, requirement := range req.Require {
		if requirement == "no_remote" {
			continue
		}
		return &ErrPolicyRequirementUnsatisfied{
			Policy:      req.Policy,
			Requirement: requirement,
		}
	}
	return nil
}

func explicitPinError(req Request, in Inputs) error {
	canonicalHarness := canonicalHarnessPin(req.Harness)
	if requirement, attemptedPin := requirementPinConflict(req, in, canonicalHarness); requirement != "" {
		return &ErrPolicyRequirementUnsatisfied{
			Policy:       req.Policy,
			Requirement:  requirement,
			AttemptedPin: attemptedPin,
		}
	}

	if canonicalHarness != "" && req.Provider != "" && !harnessCanReachProvider(in.Harnesses, canonicalHarness, req.Provider) {
		return &ErrUnsatisfiablePin{
			Pin:    "harness=" + canonicalHarness + "+provider=" + req.Provider,
			Reason: "provider is not reachable through harness",
		}
	}
	if canonicalHarness != "" && req.Model != "" {
		// Provider-routed subprocess harnesses can route any provider-pinned
		// model (lmstudio, omlx, openrouter, etc.); the harness CLI owns
		// concrete model validation in that case.
		if providerRoutedHarnessAcceptsProviderPinnedModel(canonicalHarness) && req.Provider != "" {
			return nil
		}
		h, ok := findHarness(in.Harnesses, canonicalHarness)
		if ok && h.SupportedModels != nil && !harnessSupportsModel(h.SupportedModels, req.Model) {
			return &ErrUnsatisfiablePin{
				Pin:    "harness=" + canonicalHarness + "+model=" + req.Model,
				Reason: "model is not supported by harness",
			}
		}
		if ok && h.SupportedModels == nil && !harnessCanServeExactModel(h, req.Model) {
			return &ErrUnsatisfiablePin{
				Pin:    "harness=" + canonicalHarness + "+model=" + req.Model,
				Reason: "model is not supported by harness",
			}
		}
	}
	if req.Provider != "" && req.Model != "" && !providerCanServeModel(in.Harnesses, canonicalHarness, req.Provider, req.Model) {
		return &ErrUnsatisfiablePin{
			Pin:    "provider=" + req.Provider + "+model=" + req.Model,
			Reason: "model is not available on provider",
		}
	}
	return nil
}

func providerRoutedHarnessAcceptsProviderPinnedModel(harness string) bool {
	switch harness {
	case "pi", "opencode":
		return true
	default:
		return false
	}
}

func canonicalHarnessPin(harness string) string {
	if harness == "local" {
		return "fiz"
	}
	return harness
}

func findHarness(harnesses []HarnessEntry, name string) (HarnessEntry, bool) {
	for _, h := range harnesses {
		if h.Name == name {
			return h, true
		}
	}
	return HarnessEntry{}, false
}

func harnessCanReachProvider(harnesses []HarnessEntry, harness, provider string) bool {
	h, ok := findHarness(harnesses, harness)
	if !ok {
		return false
	}
	if len(h.Providers) == 0 {
		return h.Name == provider
	}
	for _, p := range h.Providers {
		if candidateProviderIdentity(h, p) == provider {
			return true
		}
	}
	return false
}

func harnessSupportsModel(supported []string, model string) bool {

func harnessSupportsModel(supported []string, model string) bool {
	for _, candidate := range supported {
		if candidate == model {
			return true
		}
	}
	return false
}

func harnessCanServeExactModel(h HarnessEntry, model string) bool {
	if len(h.SupportedModels) > 0 && harnessSupportsModel(h.SupportedModels, model) {
		return true
	}
	if h.DefaultModel == model {
		return true
	}
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}
	for _, p := range providers {
		if p.DefaultModel == model {
			return true
		}
		if len(p.DiscoveredIDs) > 0 && FuzzyMatch(model, p.DiscoveredIDs) != "" {
			return true
		}
	}
	return false
}

func providerCanServeModel(harnesses []HarnessEntry, canonicalHarness, provider, model string) bool {
	for _, h := range harnesses {
		if canonicalHarness != "" && h.Name != canonicalHarness {
			continue
		}
		providers := h.Providers
		if len(providers) == 0 {
			providers = []ProviderEntry{{Name: ""}}
		}
		for _, p := range providers {
			if candidateProviderIdentity(h, p) != provider {
				continue
			}
			if len(p.DiscoveredIDs) > 0 {
				return FuzzyMatch(model, p.DiscoveredIDs) != ""
			}
			if p.DiscoveryAttempted {
				return false
			}
			return p.DefaultModel == "" || p.DefaultModel == model || harnessCanServeExactModel(h, model)
		}
	}
	return false
}

func requirementPinConflict(req Request, in Inputs, canonicalHarness string) (string, string) {
	if !requiresNoRemote(req) {
		return "", ""
	}
	if req.Provider == "" {
		return "", ""
	}
	for _, h := range in.Harnesses {
		if canonicalHarness != "" && h.Name != canonicalHarness {
			continue
		}
		for _, p := range h.Providers {
			if candidateProviderIdentity(h, p) == req.Provider && !candidateIsLocal(h, p) {
				return "no_remote", req.Provider
			}
		}
	}
	return "", ""
}

func requiresNoRemote(req Request) bool {
	for _, requirement := range req.Require {
		if requirement == "no_remote" {
			return true
		}
	}
	return false
}

func requestAllowsLocal(req Request) bool {
	return req.AllowLocal || req.Policy != "smart"
}

func missingPolicyRequirement(req Request, candidates []Candidate) string {
	if req.Policy == "" {
		return ""
	}
	if requiresNoRemote(req) && allCandidatesRejectedFor(candidates, FilterReasonPolicyFiltered) {
		return "no_remote"
	}
	if !requestAllowsLocal(req) && allCandidatesRejectedFor(candidates, FilterReasonPolicyFiltered) {
		return "allow_local=false"
	}
	switch req.ProviderPreference {
	case ProviderPreferenceLocalOnly:
		return "local endpoint"
	case ProviderPreferenceSubscriptionOnly:
		return "subscription harness"
	default:
		return ""
	}
}

func allCandidatesRejectedFor(candidates []Candidate, reason FilterReason) bool {
	if len(candidates) == 0 {
		return false
	}
	for _, candidate := range candidates {
		if candidate.Eligible || candidate.FilterReason != reason {
			return false
		}
	}
	return true
}

func requestedModelIntent(req Request) string {
	return req.Model
}

func hasLiveDiscoveryCandidates(candidates []rankedCandidate) bool {
	for _, c := range candidates {
		if c.out.Provider != "" && c.internal.Model == "" {
			return true
		}
		if c.out.Provider != "" && c.out.Reason != "" {
			return true
		}
	}
	return false
}

type rankedCandidate struct {
	out      Candidate
	internal candidateInternal
	// quotaExhaustedRetryAfter is non-zero when this candidate would have been
	// eligible save for its provider being in the quota_exhausted state.
	// Resolve uses this to detect the "all eligible providers quota-exhausted"
	// case and surface ErrAllProvidersQuotaExhausted.
	quotaExhaustedRetryAfter time.Time
}

// buildHarnessCandidates expands one HarnessEntry into 1..N candidates, one
// per (harness, provider, resolved-model) tuple.
func buildHarnessCandidates(h HarnessEntry, req Request, in Inputs) []rankedCandidate {
	caps := Capabilities{
		SupportsTools:      h.SupportsTools,
		SupportedReasoning: h.SupportedReasoning,
		MaxReasoningTokens: h.MaxReasoningTokens,
		SupportedPerms:     h.SupportedPerms,
		ExactPinSupport:    h.ExactPinSupport,
		SupportedModels:    h.SupportedModels,
	}

	if !h.Available {
		return []rankedCandidate{{
			out: Candidate{
				Harness:      h.Name,
				CostSource:   CostSourceUnknown,
				Reason:       "harness not available",
				FilterReason: FilterReasonUnhealthy,
			},
			internal: candidateInternal{Harness: h.Name, CostClass: h.CostClass, CostSource: CostSourceUnknown},
		}}
	}

	histRate, hasHist := in.HistoricalSuccess[h.Name]
	if !hasHist {
		histRate = -1
	}

	// Enumerate providers. For harnesses with no providers (subprocess harnesses
	// with vendor-managed billing), emit a single virtual provider entry.
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}

	out := make([]rankedCandidate, 0, len(providers))
	minCtx := req.MinContextWindow()
	stickyServerInstance := ""
	if req.CorrelationID != "" && in.StickyServerInstanceResolver != nil {
		stickyServerInstance, _ = in.StickyServerInstanceResolver(req.CorrelationID)
	}
	for _, p := range providers {
		model, reason := resolveModel(h, p, req, in)
		ctxWin := 0
		ctxSrc := ContextSourceUnknown
		if p.ContextWindows != nil {
			if v, ok := p.ContextWindows[model]; ok {
				ctxWin = v
			}
		}
		if ctxWin > 0 && p.ContextWindowSources != nil {
			if src, ok := p.ContextWindowSources[model]; ok && src != "" {
				ctxSrc = src
			}
		}
		if ctxWin == 0 && p.ContextWindow > 0 {
			ctxWin = p.ContextWindow
			if p.ContextWindowSource != "" {
				ctxSrc = p.ContextWindowSource
			}
		}
		if ctxWin == 0 && model != "" {
			ctxWin = 131072
			ctxSrc = ContextSourceDefault
		}
		if model == "" {
			ctxSrc = ContextSourceUnknown
		}
		entryCaps := caps
		entryCaps.ContextWindow = ctxWin
		entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
		if len(p.DiscoveredIDs) > 0 {
			entryCaps.SupportedModels = nil
		}

		key := ProviderModelKey(p.Name, p.EndpointName, model)
		obs := in.ObservedSpeedTPS[key]
		if obs == 0 && p.EndpointName != "" {
			obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
		}
		providerSuccessRate := -1.0
		if rate, ok := in.ProviderSuccessRate[key]; ok {
			providerSuccessRate = rate
		} else if p.EndpointName != "" {
			if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
				providerSuccessRate = rate
			}
		}
		latencyMS := in.ObservedLatencyMS[key]
		if latencyMS == 0 && p.EndpointName != "" {
			latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
		}
		power := candidatePower(in.ModelEligibility, model)
		endpointLoad := EndpointLoad{}
		if in.EndpointLoadResolver != nil {
			loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
			if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
				endpointLoad = resolved
			}
		} else if load, ok := in.EndpointLoads[key]; ok {
			endpointLoad = load
		}

		gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)
		billingKind := candidateBillingKind(h, p)

		eligible := true
		var filterReason FilterReason
		if reason == "" {
			// Subscription quota is a hard availability gate and must be
			// reported before catalog metadata gates. An exhausted Claude/Codex/
			// Gemini account is never a viable candidate, regardless of whether
			// the resolved model has complete power metadata.
			if h.IsSubscription && !h.SubscriptionOK {
				eligible = false
				reason = h.QuotaReason
				if reason == "" {
					if h.QuotaStale {
						reason = "subscription quota unavailable"
					} else {
						reason = "subscription quota exhausted"
					}
				}
				filterReason = FilterReasonUnhealthy
			} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		} else {
			eligible = false
			// resolveModel rejection — model resolution is a capability
			// mismatch with no specific public category, so fall through
			// to the catch-all.
			filterReason = FilterReasonScoredBelowTop
		}

		// Hard preference filtering.
		if eligible {
			if !requestAllowsLocal(req) && candidateIsLocal(h, p) {
				eligible = false
				reason = "policy disallows local candidates"
				filterReason = FilterReasonPolicyFiltered
			}
		}
		if eligible && requiresNoRemote(req) && !candidateIsLocal(h, p) {
			eligible = false
			reason = "policy requires no_remote"
			filterReason = FilterReasonPolicyFiltered
		}

		if eligible {
			switch req.ProviderPreference {
			case ProviderPreferenceLocalOnly:
				if !h.IsLocal {
					eligible = false
					reason = "preference is local-only"
					filterReason = FilterReasonUnhealthy
				}
			case ProviderPreferenceSubscriptionOnly:
				if !h.IsSubscription {
					eligible = false
					reason = "preference is subscription-only"
					filterReason = FilterReasonUnhealthy
				}
			}
		}

		if eligible {
			if g, fr := CheckProviderDefaultEligibility(candidateProviderIdentity(h, p), billingKind, p.ExcludeFromDefaultRouting, req); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		}

		if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
			// Hard provider pin: reject every other provider identity, even
			// when a non-pinned candidate would otherwise score higher.
			eligible = false
			reason = fmt.Sprintf("provider override requires %s", req.Provider)
			filterReason = FilterReasonPinMismatch
		}

		inCooldown := false
		if p.Name != "" && p.InCooldown {
			inCooldown = true
		} else if p.Name != "" && in.CooldownDuration > 0 {
			if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
				if in.Now.Sub(failedAt) < in.CooldownDuration {
					inCooldown = true
				}
			}
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		stickyMatch := stickyServerInstance != "" && serverInstanceMatches(stickyServerInstance, p.ServerInstance, p.EndpointName)
		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			Billing:               billingKind,
			EndpointName:          p.EndpointName,
			ServerInstance:        p.ServerInstance,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			ContextLength:         ctxWin,
			ContextSource:         ctxSrc,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
			EndpointLoad:          endpointLoad.NormalizedLoad,
			EndpointLoadFresh:     endpointLoad.UtilizationFresh,
			EndpointSaturated:     endpointLoad.UtilizationSaturated,
			StickyMatch:           stickyMatch,
			MinPower:              req.MinPower,
			MaxPower:              req.MaxPower,
		}
		if eligible && ctxWin > 0 && minCtx > 0 {
			ci.ContextHeadroom = ctxWin - minCtx
		}
		out = append(out, rankedCandidate{
			out: Candidate{
				Harness:            h.Name,
				Provider:           p.Name,
				Billing:            billingKind,
				Endpoint:           p.EndpointName,
				ServerInstance:     p.ServerInstance,
				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				ContextLength:      ctxWin,
				ContextSource:      ctxSrc,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				Utilization:        endpointLoad.NormalizedLoad,
				ContextHeadroom:    ci.ContextHeadroom,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
				StickyAffinity: func() float64 {
					if stickyMatch {
						return StickyAffinityBonus
					}
					return 0
				}(),
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

func candidateProviderIdentity(h HarnessEntry, p ProviderEntry) string {
	if p.Name != "" {
		return p.Name
	}
	return h.Name
}

func candidateBillingKind(h HarnessEntry, p ProviderEntry) modelcatalog.BillingModel {
	if p.Billing != modelcatalog.BillingModelUnknown {
		return p.Billing
	}
	if h.IsSubscription {
		return modelcatalog.BillingModelSubscription
	}
	if candidateIsLocal(h, p) {
		return modelcatalog.BillingModelFixed
	}
	if billing := modelcatalog.BillingForProviderSystem(candidateProviderIdentity(h, p)); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	if billing := modelcatalog.BillingForHarness(h.Name); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	return modelcatalog.BillingModelUnknown
}

func candidateIsLocal(h HarnessEntry, p ProviderEntry) bool {
	return candidateCostClass(h, p) == "local" || (p.CostClass == "" && h.IsLocal)
}

